#!/usr/bin/env bash
# Some portions generated by Codex. Separate diagnostic recordings, never clean timing data.
set -euo pipefail
cd "$(dirname "$0")/../../.."
: "${CP_A:?}" "${CP_B:?}" "${LOCK:?}" "${BASELINE_SHA:?}" "${CANDIDATE_SHA:?}" "${CELLS_FILE:?}"
JAVA=${JAVA:-../toolchain/jdk-25.0.5+8/bin/java}; JAVAC=${JAVAC:-../toolchain/jdk-25.0.5+8/bin/javac}; JFR=${JFR:-../toolchain/jdk-25.0.5+8/bin/jfr}
OUT=${OUT:-experiments/threadlocal-audit/record-cancellation/profiles-01}
[[ ! -e $OUT ]] || { echo "Refuse existing output $OUT" >&2; exit 2; }
mkdir -p "$OUT/harness"
exec 9>"$LOCK"; flock 9
"$JAVAC" -cp "$CP_B" -d "$OUT/harness" experiments/threadlocal-audit/record-cancellation/RecordCancellationQueryBenchmark.java
cp "$CELLS_FILE" "$OUT/cells.tsv"
mapfile -t FLAGS < experiments/threadlocal-audit/best-flags.txt
FLAGS+=(-Drdf4j.lmdb.queryMemory.perQueryMaxBytes=671088640 -Drdf4j.lmdb.recordCancellation.trace=false)
{
 date -u; "$JAVA" -version; echo BASELINE_SHA="$BASELINE_SHA" CANDIDATE_SHA="$CANDIDATE_SHA"
 printf 'CP_A=%s\nCP_B0_B1=%s\n' "$CP_A" "$CP_B"
 printf '%s\n' "${FLAGS[@]}"
 sha256sum experiments/threadlocal-audit/record-cancellation/RecordCancellationQueryBenchmark.java "$OUT/cells.tsv"
} > "$OUT/environment.txt" 2>&1
while IFS=$'\t' read -r cell regime shape adjacency groups; do
 [[ -z $cell || $cell == \#* ]] && continue
 for arm in A B0 B1; do
  cp=$CP_B; on=false; [[ $arm == A ]] && cp=$CP_A; [[ $arm == B1 ]] && on=true
  file="$(realpath "$OUT")/$cell-$arm"; iterations=30; [[ $regime == regular ]] && iterations=5
  "$JAVA" --enable-native-access=ALL-UNNAMED -Xms2g -Xmx3g "${FLAGS[@]}" "-Drdf4j.lmdb.recordCancellation.owned=$on" \
   "-Daudit.regime=$regime" "-Daudit.shape=$shape" "-Daudit.adjacency=$adjacency" -Doverlay.benchmark.warmups=20 \
   "-Daudit.jfr=$file.jfr" -cp "$OUT/harness:$cp" org.eclipse.rdf4j.sail.lmdb.evaluation.RecordCancellationQueryBenchmark \
   "$groups" 10 "$iterations" true > "$file.log" 2>&1
  "$JFR" print --json --events jdk.ExecutionSample,jdk.NativeMethodSample "$file.jfr" > "$file.samples.json"
 done
done < "$OUT/cells.tsv"
python3 experiments/threadlocal-audit/summarize-profiles.py "$OUT" > "$OUT/summary.json"
